//! Which seedling replants a ripe crop (`plants.tsv`, generated by
//! `research/scripts/plants.py` from the `farm_dump` EML export). A ripe crop is told
//! apart by the harvest it holds: `ecs::DefaultInventory.defaultInventory` of its stage.

use std::collections::HashMap;
use std::sync::OnceLock;

const TABLE: &str = include_str!("../plants.tsv");

#[derive(Clone, Debug, PartialEq)]
pub struct Crop {
    pub seedling: u32,
    pub name: String,
    /// for a ripe stage that is scatter loot (beans …): what picking it gives, (item,
    /// count); its inventory is applied only then, so nothing is stored to take
    pub harvest: Vec<(u32, u32)>,
}

/// Harvest inventory guid -> the crop.
pub fn crops() -> &'static HashMap<String, Crop> {
    static CROPS: OnceLock<HashMap<String, Crop>> = OnceLock::new();
    CROPS.get_or_init(|| {
        TABLE
            .lines()
            .filter_map(|line| {
                let p: Vec<&str> = line.split('\t').collect();
                if p.len() < 4 || p[0] != "crop" {
                    return None;
                }
                let harvest = p.get(5).map_or_else(Vec::new, |h| {
                    h.split(',').filter_map(|s| {
                        let (item, count) = s.split_once(':')?;
                        Some((item.parse().ok()?, count.parse().ok()?))
                    }).collect()
                });
                Some((p[1].to_string(), Crop { seedling: p[2].parse().ok()?, name: p[3].into(), harvest }))
            })
            .collect()
    })
}

/// Growing stage inventory guid -> the harvest inventory guid of its crop (`stage` rows).
pub fn stages() -> &'static HashMap<String, String> {
    static STAGES: OnceLock<HashMap<String, String>> = OnceLock::new();
    STAGES.get_or_init(|| {
        TABLE
            .lines()
            .filter_map(|line| {
                let p: Vec<&str> = line.split('\t').collect();
                (p.len() >= 3 && p[0] == "stage").then(|| (p[1].to_string(), p[2].to_string()))
            })
            .collect()
    })
}

/// The crop a stage belongs to (by its inventory guid), and whether it is the ripe one.
pub fn crop_of(inventory: &str) -> Option<(&'static Crop, bool)> {
    match crops().get(inventory) {
        Some(crop) => Some((crop, true)),
        None => crops().get(stages().get(inventory)?).map(|crop| (crop, false)),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn corn_is_replanted_with_corn_seedlings() {
        let corn = &crops()["304ab9b0-dbe8-451e-8eb0-8f238c286cf5"];
        assert_eq!(corn.name, "T1_Plant_Growth_Corn");
        assert_eq!(crate::names::item(corn.seedling), "Seedling Grain Corn");
        assert_eq!(crops().len(), 36);
        let bean = &crops()["18280ed9-7665-445f-ae97-8dadd3d820bb"];
        assert_eq!((crate::names::item(bean.seedling).as_str(), bean.harvest.len()), ("Seedling Vegetable Bean", 1));
        // a bean seedling stage is known as a growing bean
        let (crop, ripe) = crop_of("6cb7105a-7fe0-4265-b058-db5d4c26ed1c").unwrap();
        assert_eq!((crop.name.as_str(), ripe), ("T7_Plant_Growth_Bean", false));
    }
}
